#include <vector>
#include <complex>
#include <algorithm>
#include <cmath>
#include <cstddef>
#include <omp.h>

void sortComplexByMagnitude(std::vector<std::complex<double>> &x) {
    const std::size_t n = x.size();
    if (n < 2) return;

    // Parallel stable merge sort: sort chunks in parallel, then merge rounds.
    const int maxThreads = omp_get_max_threads();
    const std::size_t chunkSize = std::max<std::size_t>(1, (n + (std::size_t)maxThreads - 1) / (std::size_t)maxThreads);

    auto cmp = [](const std::complex<double>& a, const std::complex<double>& b) {
        // Compare by squared magnitude (avoids sqrt), tie-break by real then imag for determinism
        const double ma = std::norm(a);
        const double mb = std::norm(b);
        if (ma < mb) return true;
        if (ma > mb) return false;
        if (a.real() < b.real()) return true;
        if (a.real() > b.real()) return false;
        return a.imag() < b.imag();
    };

    // 1) Sort chunks independently.
    #pragma omp parallel for schedule(static)
    for (std::ptrdiff_t i = 0; i < (std::ptrdiff_t)n; i += (std::ptrdiff_t)chunkSize) {
        const std::size_t begin = (std::size_t)i;
        const std::size_t end   = std::min(n, begin + chunkSize);
        std::stable_sort(x.begin() + (std::ptrdiff_t)begin, x.begin() + (std::ptrdiff_t)end, cmp);
    }

    // Temporary buffer for merges.
    std::vector<std::complex<double>> tmp(n);

    // 2) Merge in rounds: width doubles each round.
    // We alternate source/destination between x and tmp each round.
    bool srcIsX = true;
    for (std::size_t width = chunkSize; width < n; width *= 2) {
        std::vector<std::complex<double>> &src = srcIsX ? x : tmp;
        std::vector<std::complex<double>> &dst = srcIsX ? tmp : x;

        #pragma omp parallel for schedule(static)
        for (std::ptrdiff_t left = 0; left < (std::ptrdiff_t)n; left += (std::ptrdiff_t)(2 * width)) {
            const std::size_t l = (std::size_t)left;
            const std::size_t m = std::min(n, l + width);
            const std::size_t r = std::min(n, l + 2 * width);

            std::merge(src.begin() + (std::ptrdiff_t)l,
                       src.begin() + (std::ptrdiff_t)m,
                       src.begin() + (std::ptrdiff_t)m,
                       src.begin() + (std::ptrdiff_t)r,
                       dst.begin() + (std::ptrdiff_t)l,
                       cmp);
        }

        srcIsX = !srcIsX;
    }

    // If the final data ended up in tmp, copy back to x.
    if (!srcIsX) {
        x.swap(tmp);
    }
}
